    # Extended Euclidean algorithm
    a = [0, 1]
    q = [None, None]
    r = [n, x]
    i = 1
    while r[i] > 1:
        i += 1
        r.append(r[i-2] % r[i-1])
        q.append(r[i-2] // r[i-1])
        a.append((a[i-2] - q[i] * a[i-1]) % n)
