def kasiski_key_lengths(alpha, max_len):
    # find repeated n-grams, collect distances, factor counts
    positions = {}
    for i in range(len(alpha) - 2):
        ngram = alpha[i:i+3]
        positions.setdefault(ngram, []).append(i)
    factor_counts = Counter()
    for locs in positions.values():
        if len(locs) < 2:
            continue
        for j in range(1, len(locs)):
            dist = locs[j] - locs[j-1]
            for f in range(2, min(dist + 1, max_len + 1)):
                if dist % f == 0:
                    factor_counts[f] += 1
    return [k for k, _ in factor_counts.most_common(10)]

