def crt_collapse(y1, y2, a1, a2, q1, q2):
    Q = q1 * q2
    u = (q2 * inverse(q2, q1)) % Q  # ≡ 1 mod q1, 0 mod q2
    v = (q1 * inverse(q1, q2)) % Q  # ≡ 0 mod q1, 1 mod q2
    A = (a1 * u + a2 * v) % Q
