def decode_base64(encoded, alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/', padding='='):
    # Remove padding characters from the end
    encoded = encoded.rstrip(padding)
    # Map characters to 6-bit values
    bits = ''
    for ch in encoded:
        if ch in alphabet:
            val = alphabet.index(ch)
            bits += format(val, '06b')
        else:
            # Ignore non-alphabet characters (or handle error)
            pass
    # Discard trailing bits not forming a full byte
    bytes_out = bytearray()
    for i in range(0, len(bits) - len(bits) % 8, 8):
        byte = int(bits[i:i+8], 2)
        bytes_out.append(byte)
    return bytes(bytes_out)

